# 去除重复的ISBN（字典中后面的值会覆盖前面的）
# 这里保留唯一的ISBN
LOCAL_TEXTBOOK_DB_UNIQUE = {}
for isbn, info in LOCAL_TEXTBOOK_DB.items():
    if isbn not in LOCAL_TEXTBOOK_DB_UNIQUE:
        LOCAL_TEXTBOOK_DB_UNIQUE[isbn] = info

# 使用去重后的数据库
LOCAL_TEXTBOOK_DB = LOCAL_TEXTBOOK_DB_UNIQUE


def _query_openlibrary(isbn: str) -> dict | None:
    """查询 OpenLibrary 国际书籍数据库"""
    try:
        resp = requests.get(
            f'https://openlibrary.org/isbn/{isbn}.json',
            timeout=3,
        )
        if resp.status_code != 200:
            return None

        data = resp.json()
        title = data.get('title', '')
        if not title:
            return None

        # OpenLibrary 作者是 URL 引用，需二次请求获取名字
        author = ''
        author_refs = data.get('authors', [])
        if author_refs:
            first_key = author_refs[0].get('key', '')
            if first_key:
                try:
                    a_resp = requests.get(
                        f'https://openlibrary.org{first_key}.json',
                        timeout=2,
                    )
                    if a_resp.status_code == 200:
                        author = a_resp.json().get('name', '')
                except requests.RequestException:
                    pass

        publishers = data.get('publishers', [])
        publisher = publishers[0] if publishers else ''

        return {
            'isbn': isbn,
            'title': title,
            'author': author,
            'lookup_url': f'https://openlibrary.org/isbn/{isbn}',
            'source': 'openlibrary',
            'confidence': 'medium' if author else 'low',
        }
    except requests.RequestException:
        return None


def lookup_isbn(isbn: str) -> dict:
    """通过 ISBN 查询书籍信息

    查询优先级:
      1. 本地教材库 (0ms) - 80+ 本浙大常用教材
      2. CourseBook 数据库 (~1ms) - seed_courses 数据
      3. OpenLibrary (~3s) - 国际数据库
      4. 降级返回空 - 引导手动填写
    """
    isbn = isbn.strip().replace('-', '').replace(' ', '')

    # 校验 ISBN 格式
    if not isbn or not (len(isbn) == 10 or len(isbn) == 13):
        return {
            'isbn': isbn,
            'title': '',
            'author': '',
            'publisher': '',
            'cover_url': '',
            'source': 'invalid',
            'error': 'ISBN 格式不正确，应为 10 位或 13 位数字',
        }

    # L1: 本地教材库 (0ms)
    if isbn in LOCAL_TEXTBOOK_DB:
        entry = LOCAL_TEXTBOOK_DB[isbn]
        return {
            'isbn': isbn,
            'title': entry['title'],
            'author': entry['author'],
            'publisher': entry['publisher'],
            'cover_url': '',
            'source': 'local',
            'confidence': 'high',
        }

    # L2: CourseBook 数据库
    try:
        from models import CourseBook
        cb = CourseBook.query.filter_by(book_isbn=isbn).first()
        if cb:
            return {
                'isbn': isbn,
                'title': cb.book_title,
                'author': cb.book_author or '',
                'publisher': '',
                'cover_url': '',
                'source': 'course_db',
                'confidence': 'high',
            }
    except Exception:
        pass

    # L3: OpenLibrary
    result = _query_openlibrary(isbn)
    if result:
        return result

    # L4: 降级返回空
    return {
        'isbn': isbn,
        'title': '',
        'author': '',
        'publisher': '',
        'cover_url': '',
        'source': 'manual',
    }